const items = $input.all();
const recipes = [];

for (const item of items) {
  // Le HTML est dans data
  const htmlContent = item.json.data;

  if (!htmlContent) continue;

  // Extraire le JSON-LD du HTML
  const regex = /<script type="application\/ld\+json">\s*([\s\S]*?)\s*<\/script>/g;
  let match;

  while ((match = regex.exec(htmlContent)) !== null) {
    try {
      const jsonData = JSON.parse(match[1]);

      // Chercher le type Recipe
      if (jsonData['@type'] === 'Recipe') {
        const formatted = {
          titre: jsonData.name,
          categorie: jsonData.recipeCategory || jsonData.recipeCuisine,
          temps_preparation: jsonData.prepTime,
          temps_cuisson: jsonData.cookTime,
          temps_total: jsonData.totalTime,
          portions: jsonData.recipeYield,
          ingredients: jsonData.recipeIngredient || [],
          etapes: (jsonData.recipeInstructions || []).map(step => 
            typeof step === 'string' ? step : step.text
          ),
          auteur: jsonData.author,
          description: jsonData.description,
          note: jsonData.aggregateRating ? {
            valeur: jsonData.aggregateRating.ratingValue,
            nombre_avis: jsonData.aggregateRating.reviewCount
          } : null
        };

        recipes.push(formatted);
      }
    } catch (e) {
      console.error('Erreur parsing JSON-LD:', e.message);
    }
  }
}

console.log('Recettes trouvées:', recipes.length);

return [{
  json: {
    recettes_extraites: JSON.stringify(recipes, null, 2),
    nombre_recettes: recipes.length
  }
}];

const recipe = $input.item.json.recipe_json;

if (!recipe) {
  return { json: { error: 'No recipe data available', url: $input.item.json.url } };
}

// Parser durées ISO 8601
function parseISODuration(duration) {
  if (!duration) return null;
  const match = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?/);
  if (!match) return null;
  const hours = parseInt(match[1] || 0);
  const minutes = parseInt(match[2] || 0);
  return hours * 60 + minutes;
}

// Parser portions
function parseServings(yieldValue) {
  if (!yieldValue) return null;
  const match = String(yieldValue).match(/(\d+)/);
  return match ? parseInt(match[1]) : null;
}

const prepTime = parseISODuration(recipe.prepTime);
const cookTime = parseISODuration(recipe.cookTime);
const totalTime = (prepTime || 0) + (cookTime || 0) || null;

// Retourne uniquement les données structurées
return { 
  json: { 
    title: recipe.name || 'Sans titre',
    category: recipe.recipeCategory || null,
    servings: parseServings(recipe.recipeYield),
    prep_time: prepTime,
    cook_time: cookTime,
    total_time: totalTime,
    ingredients: (recipe.recipeIngredient || []).slice(0, 20),
    instructions: (recipe.recipeInstructions || [])
      .map(step => typeof step === 'string' ? step : step.text)
      .filter(Boolean)
      .slice(0, 15),
    original_url: $input.item.json.url
  } 
};

let output = $input.item.json.output || $input.item.json.response || $input.item.json.text;

// Nettoyer le JSON
output = output
  .replace(/```json|```/g, '')
  .replace(/,(\s*[}\]])/g, '$1')
  .trim();

console.log('Position 1048:', output.substring(1040, 1060));

try {
  const parsed = JSON.parse(output);
  return [{ json: parsed }];
} catch (e) {
  console.error('Erreur:', e.message);
  console.log('JSON problématique:', output);
  throw e;
}

const html = $input.item.json.html;

if (!html) {
  return { json: { error: 'No HTML content', url: $input.item.json.url } };
}

// Fonction pour nettoyer le texte
function cleanText(text) {
  return text
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '') // Vire les scripts
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '') // Vire les styles
    .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, '') // Vire la navigation
    .replace(/<header\b[^<]*(?:(?!<\/header>)<[^<]*)*<\/header>/gi, '') // Vire le header
    .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, '') // Vire le footer
    .replace(/<aside\b[^<]*(?:(?!<\/aside>)<[^<]*)*<\/aside>/gi, '') // Vire les sidebars
    .replace(/<!--[\s\S]*?-->/g, '') // Vire les commentaires
    .replace(/<[^>]+>/g, ' ') // Vire toutes les balises HTML
    .replace(/\s+/g, ' ') // Normalise les espaces
    .trim();
}

// Extraction basique avec regex pour structurer un minimum
const recipe = {
  title: null,
  ingredients: [],
  instructions: [],
  metadata: {}
};

// Titre (premier h1)
const titleMatch = html.match(/<h1[^>]*>(.*?)<\/h1>/i);
if (titleMatch) {
  recipe.title = titleMatch[1].replace(/<[^>]*>/g, '').trim();
}

// Zone ingrédients (cherche les sections probables)
const ingredientPatterns = [
  /<ul[^>]*class="[^"]*ingredient[^"]*"[^>]*>([\s\S]*?)<\/ul>/gi,
  /<div[^>]*class="[^"]*ingredient[^"]*"[^>]*>([\s\S]*?)<\/div>/gi,
  /<section[^>]*id="[^"]*ingredient[^"]*"[^>]*>([\s\S]*?)<\/section>/gi
];

for (const pattern of ingredientPatterns) {
  const matches = [...html.matchAll(pattern)];
  for (const match of matches) {
    const section = match[1];
    const liMatches = section.matchAll(/<li[^>]*>(.*?)<\/li>/gi);
    for (const li of liMatches) {
      const text = li[1].replace(/<[^>]*>/g, '').trim();
      if (text && text.length > 2) {
        recipe.ingredients.push(text);
      }
    }
  }
}

// Zone instructions (cherche les sections probables)
const instructionPatterns = [
  /<ol[^>]*class="[^"]*step[^"]*"[^>]*>([\s\S]*?)<\/ol>/gi,
  /<ol[^>]*class="[^"]*instruction[^"]*"[^>]*>([\s\S]*?)<\/ol>/gi,
  /<div[^>]*class="[^"]*step[^"]*"[^>]*>([\s\S]*?)<\/div>/gi
];

for (const pattern of instructionPatterns) {
  const matches = [...html.matchAll(pattern)];
  for (const match of matches) {
    const section = match[1];
    const liMatches = section.matchAll(/<li[^>]*>(.*?)<\/li>/gi);
    let stepNum = 1;
    for (const li of liMatches) {
      const text = li[1].replace(/<[^>]*>/g, '').trim();
      if (text && text.length > 10) {
        recipe.instructions.push(text);
        stepNum++;
      }
    }
  }
}

// Métadonnées (temps, portions)
const metaText = html.substring(0, 5000); // Cherche dans le début de page
const prepMatch = metaText.match(/pr[ée]paration[:\s]*(\d+)\s*min/i);
const cookMatch = metaText.match(/cuisson[:\s]*(\d+)\s*min/i);
const servingsMatch = metaText.match(/(\d+)\s*personnes?/i);

if (prepMatch) recipe.metadata.prep_time = parseInt(prepMatch[1]);
if (cookMatch) recipe.metadata.cook_time = parseInt(cookMatch[1]);
if (servingsMatch) recipe.metadata.servings = parseInt(servingsMatch[1]);

// Texte nettoyé pour Ollama (fallback si extraction structurée échoue)
const cleanedText = cleanText(html);

return {
  json: {
    source: "html_extraction",
    url: $input.item.json.url,
    title: recipe.title,
    ingredients: recipe.ingredients,
    instructions: recipe.instructions,
    metadata: recipe.metadata,
    cleaned_html_text: cleanedText.substring(0, 8000), // Limite à 8000 chars pour Ollama
    has_structured_data: recipe.ingredients.length > 0 && recipe.instructions.length > 0
  }
};

const items = $input.all();

const ingredients = items.map(item => ({
  id: item.json.id,
  name: item.json.name,
  slug: item.json.slug,
  category: item.json.category
}));

// Convertit en JSON string pour Ollama
return [{
  json: {
    reference_ingredients: JSON.stringify(ingredients, null, 2),
    count: ingredients.length
  }
}];

// Récupérer tous les ingrédients du node Switch
const ingredients = $input.all().map(item => ({
  name: item.json.name,
  quantity: item.json.quantity,
  unit: item.json.unit
}));

return [{
  json: {
    ingredients_to_match: JSON.stringify(ingredients, null, 2)
  }
}];
